   808  static bool find_section_end(struct config *config)
   809  {
   810      struct config_line *line;
   811      int cur_level = 1;
   812
   813      if (config->error_message)
   814          return false;
   815
   816      while (parser_next(&config->parser, &line)) {
   817          if (line->type == CONFIG_LINE_TYPE_SECTION) {
   818              cur_level++;
   819          } else if (line->type == CONFIG_LINE_TYPE_SECTION_END) {
   820              cur_level--;
   821
   822              if (!cur_level)
   823                  return true;
   824          }
   825      }
   826
   827      return false;
   828  }
