    31  #define DEFINE_RING_BUFFER_TYPE(type_name_, element_type_, size_)              \
    32      static_assert((size_) && !((size_) & ((size_)-1)),                         \
    33                    "size is a power of two");                                   \
    34                                                                                 \
    35      struct type_name_ {                                                        \
    36          uint32_t read, write;                                                  \
    37          element_type_ array[size_];                                            \
    38      };                                                                         \
    39                                                                                 \
    40      __attribute__((unused)) static inline uint32_t type_name_##_mask(          \
    41          uint32_t value)                                                        \
    42      {                                                                          \
    43          return value & ((size_)-1);                                            \
    44      }                                                                          \
    45                                                                                 \
    46      __attribute__((unused)) static inline uint32_t type_name_##_size(          \
    47          const struct type_name_ *rb)                                           \
    48      {                                                                          \
    49          return rb->write - rb->read;                                           \
    50      }                                                                          \
    51                                                                                 \
    52      __attribute__((unused)) static inline bool type_name_##_full(              \
    53          const struct type_name_ *rb)                                           \
    54      {                                                                          \
    55          return type_name_##_size(rb) == (size_);                               \
    56      }                                                                          \
    57                                                                                 \
    58      __attribute__((unused)) static inline bool type_name_##_empty(             \
    59          const struct type_name_ *rb)                                           \
    60      {                                                                          \
    61          return rb->write == rb->read;                                          \
    62      }                                                                          \
    63                                                                                 \
    64      __attribute__((unused)) static inline void type_name_##_init(              \
    65          struct type_name_ *rb)                                                 \
    66      {                                                                          \
    67          rb->write = rb->read = 0;                                              \
    68      }                                                                          \
    69                                                                                 \
    70      __attribute__((unused)) static inline void type_name_##_put(               \
    71          struct type_name_ *rb, element_type_ *e)                               \
    72      {                                                                          \
    73          assert(!type_name_##_full(rb));                                        \
    74          memcpy(&rb->array[type_name_##_mask(rb->write++)], e, sizeof(*e));     \
    75      }                                                                          \
    76                                                                                 \
    77      __attribute__((unused)) static inline element_type_ type_name_##_get(      \
    78          struct type_name_ *rb)                                                 \
    79      {                                                                          \
    80          assert(!type_name_##_empty(rb));                                       \
    81          return rb->array[type_name_##_mask(rb->read++)];                       \
    82      }                                                                          \
    83                                                                                 \
    84      __attribute__((unused)) static inline element_type_ *type_name_##_get_ptr( \
    85          struct type_name_ *rb)                                                 \
    86      {                                                                          \
    87          assert(!type_name_##_empty(rb));                                       \
    88          return &rb->array[type_name_##_mask(rb->read++)];                      \
    89      }
